      SUBROUTINE GETVISCPARAMS(RVISC,NSURF,PROPS,NPROPS)
C
C      INCLUDE 'ABA_PARAM.INC'
C
      IMPLICIT NONE
C
      DOUBLE PRECISION RVISC(NSURF),PROPS(NPROPS)
      INTEGER NSURF,NPROPS
      RVISC=0.D0
C     IST_SET VISCP: START
      RVISC(1)=DBLE(PROPS(29))
C     IST_SET VISCP: END
      RETURN
      END
