      SUBROUTINE CALCSURF(RF,NF,STR_TDT,NSTR,RQ,NH,PROPS,NPROPS,NORDER)
C
C      INCLUDE 'ABA_PARAM.INC'
C
      IMPLICIT NONE
C
      DOUBLE PRECISION STR_TDT(NSTR),RF(NF),PROPS(NPROPS),RQ(NH)
      INTEGER NORDER(NF)
      INTEGER NF,NPROPS,NSTR,NH
C
      RF=0.D0
C     IST_SET FSURF: START
      RF(NORDER(1))=DBLE(PROPS(16))*(STR_TDT(1)+STR_TDT(5)+
     + STR_TDT(9))*DBLE(0.3333333333333333)*(DBLE(PROPS(19))*RQ(1)+
     + DBLE(1))+DBLE(PROPS(17))*DBLE(-1)*(DBLE(PROPS(20))*RQ(1)+
     + DBLE(1))+
     + DBLE(3)**DBLE(-0.5)*(DBLE(PROPS(7))**DBLE(-2)*(DBLE(PROPS(24))*DB
     + LE(2
     + )*(STR_TDT(10)**DBLE(2)+STR_TDT(14)**DBLE(2)+
     + STR_TDT(18)**DBLE(2)+STR_TDT(14)*STR_TDT(18)*DBLE(-1)+
     + STR_TDT(10)*(STR_TDT(14)+STR_TDT(18))*DBLE(-1)+
     + STR_TDT(11)*STR_TDT(13)*DBLE(3)+
     + STR_TDT(12)*STR_TDT(16)*DBLE(3)+
     + STR_TDT(15)*STR_TDT(17)*DBLE(3))+
     + DBLE(PROPS(23))*((STR_TDT(10)**DBLE(2)+STR_TDT(14)**DBLE(2)+
     + STR_TDT(18)**DBLE(2)+STR_TDT(14)*STR_TDT(18)*DBLE(-1)+
     + STR_TDT(10)*(STR_TDT(14)+STR_TDT(18))*DBLE(-1))*DBLE(2)+
     + (STR_TDT(11)**DBLE(2)+STR_TDT(12)**DBLE(2)+
     + STR_TDT(13)**DBLE(2)+STR_TDT(15)**DBLE(2)+
     + STR_TDT(16)**DBLE(2)+STR_TDT(17)**DBLE(2))*DBLE(3))+
     + DBLE(PROPS(7))**DBLE(2)*(DBLE(PROPS(22))*DBLE(2)*(STR_TDT(1)**DBL
     + E(2)+STR_TDT(5)**DBLE(2)+STR_TDT(9)**DBLE(2)+
     + STR_TDT(1)*STR_TDT(5)*DBLE(-1)+(STR_TDT(1)+
     + STR_TDT(5))*STR_TDT(9)*DBLE(-1)+
     + STR_TDT(2)*STR_TDT(4)*DBLE(3)+STR_TDT(3)*STR_TDT(7)*DBLE(3)
     + +STR_TDT(6)*STR_TDT(8)*DBLE(3))+
     + DBLE(PROPS(21))*((STR_TDT(1)**DBLE(2)+STR_TDT(5)**DBLE(2)+
     + STR_TDT(9)**DBLE(2)+STR_TDT(1)*STR_TDT(5)*DBLE(-1)+
     + (STR_TDT(1)+STR_TDT(5))*STR_TDT(9)*DBLE(-1))*DBLE(2)+
     + (STR_TDT(2)**DBLE(2)+STR_TDT(3)**DBLE(2)+STR_TDT(4)**DBLE(2)
     + +STR_TDT(6)**DBLE(2)+STR_TDT(7)**DBLE(2)+
     + STR_TDT(8)**DBLE(2))*DBLE(3)))))**DBLE(0.5)
C     IST_SET FSURF: END
      RETURN
      END
