     + (STR_TDT(2)**DBLE(2)+STR_TDT(3)**DBLE(2)+STR_TDT(4)**DBLE(2)
     + +STR_TDT(6)**DBLE(2)+STR_TDT(7)**DBLE(2)+
     + STR_TDT(8)**DBLE(2))*DBLE(3)))))**DBLE(-0.5)*(DBLE(PROPS(23))*DBL
     + E(4)
     + +DBLE(PROPS(24))*DBLE(4))
C     IST_SET DGDSS: END
      RETURN
      END
