C
      SUBROUTINE GETELSTRAIN(EEL,STR_TDT,NSTR,RQ,NH,PROPS,NPROPS)
C
C      INCLUDE 'ABA_PARAM.INC'
C
      IMPLICIT NONE
C
      DOUBLE PRECISION EEL(NSTR),STR_TDT(NSTR),PROPS(NPROPS),RQ(NH)
      INTEGER NSTR,NH,NPROPS
      EEL=0.D0
C     IST_SET EEL: START
      EEL(1)=DBLE(PROPS(1))**DBLE(-1)*DBLE(PROPS(2))**DBLE(-1)*DBLE(0.0
     + 555
     + 5555555555555)*(DBLE(PROPS(2))*(STR_TDT(1)+STR_TDT(5)+
     + STR_TDT(9))*DBLE(2)+DBLE(PROPS(1))*((STR_TDT(5)+
     + STR_TDT(9))*DBLE(-3)+STR_TDT(1)*DBLE(6)))
      EEL(2)=DBLE(PROPS(2))**DBLE(-1)*DBLE(PROPS(3))**DBLE(-1)*(DBLE(PR
     + O
     + PS(3))*(STR_TDT(2)+STR_TDT(4))+
     + DBLE(PROPS(2))*(STR_TDT(2)+STR_TDT(4)*DBLE(-1)))*DBLE(0.25)
      EEL(3)=DBLE(PROPS(2))**DBLE(-1)*DBLE(PROPS(3))**DBLE(-1)*(DBLE(PR
     + O
     + PS(3))*(STR_TDT(3)+STR_TDT(7))+
     + DBLE(PROPS(2))*(STR_TDT(3)+STR_TDT(7)*DBLE(-1)))*DBLE(0.25)
      EEL(4)=DBLE(PROPS(2))**DBLE(-1)*DBLE(PROPS(3))**DBLE(-1)*(DBLE(PR
     + O
     + PS(3))*(STR_TDT(2)+STR_TDT(4))+
     + DBLE(PROPS(2))*(STR_TDT(4)+STR_TDT(2)*DBLE(-1)))*DBLE(0.25)
      EEL(5)=DBLE(PROPS(1))**DBLE(-1)*DBLE(PROPS(2))**DBLE(-1)*DBLE(0.0
     + 555
     + 5555555555555)*(DBLE(PROPS(1))*DBLE(-3)*(STR_TDT(1)+STR_TDT(9)
     + +STR_TDT(5)*DBLE(-2))+DBLE(PROPS(2))*(STR_TDT(1)+
     + STR_TDT(5)+STR_TDT(9))*DBLE(2))
      EEL(6)=DBLE(PROPS(2))**DBLE(-1)*DBLE(PROPS(3))**DBLE(-1)*(DBLE(PR
     + O
     + PS(3))*(STR_TDT(6)+STR_TDT(8))+
     + DBLE(PROPS(2))*(STR_TDT(6)+STR_TDT(8)*DBLE(-1)))*DBLE(0.25)
      EEL(7)=DBLE(PROPS(2))**DBLE(-1)*DBLE(PROPS(3))**DBLE(-1)*(DBLE(PR
     + O
     + PS(3))*(STR_TDT(3)+STR_TDT(7))+
     + DBLE(PROPS(2))*(STR_TDT(7)+STR_TDT(3)*DBLE(-1)))*DBLE(0.25)
      EEL(8)=DBLE(PROPS(2))**DBLE(-1)*DBLE(PROPS(3))**DBLE(-1)*(DBLE(PR
     + O
     + PS(3))*(STR_TDT(6)+STR_TDT(8))+
     + DBLE(PROPS(2))*(STR_TDT(8)+STR_TDT(6)*DBLE(-1)))*DBLE(0.25)
      EEL(9)=DBLE(PROPS(1))**DBLE(-1)*DBLE(PROPS(2))**DBLE(-1)*DBLE(0.0
     + 555
     + 5555555555555)*(DBLE(PROPS(1))*DBLE(-3)*(STR_TDT(1)+STR_TDT(5)
     + +STR_TDT(9)*DBLE(-2))+DBLE(PROPS(2))*(STR_TDT(1)+
     + STR_TDT(5)+STR_TDT(9))*DBLE(2))
      EEL(10)=DBLE(PROPS(4))**DBLE(-1)*DBLE(PROPS(5))**DBLE(-1)*DBLE(0.
     + 055
     + 55555555555555)*(DBLE(PROPS(5))*(STR_TDT(10)+STR_TDT(14)+
     + STR_TDT(18))*DBLE(2)+DBLE(PROPS(4))*((STR_TDT(14)+
     + STR_TDT(18))*DBLE(-3)+STR_TDT(10)*DBLE(6)))
      EEL(11)=DBLE(PROPS(5))**DBLE(-1)*DBLE(PROPS(6))**DBLE(-1)*(DBLE(P
     + R
     + OPS(6))*(STR_TDT(11)+STR_TDT(13))+
     + DBLE(PROPS(5))*(STR_TDT(11)+STR_TDT(13)*DBLE(-1)))*DBLE(0.25)
      EEL(12)=DBLE(PROPS(5))**DBLE(-1)*DBLE(PROPS(6))**DBLE(-1)*(DBLE(P
     + R
     + OPS(6))*(STR_TDT(12)+STR_TDT(16))+
     + DBLE(PROPS(5))*(STR_TDT(12)+STR_TDT(16)*DBLE(-1)))*DBLE(0.25)
      EEL(13)=DBLE(PROPS(5))**DBLE(-1)*DBLE(PROPS(6))**DBLE(-1)*(DBLE(P
     + R
     + OPS(6))*(STR_TDT(11)+STR_TDT(13))+
     + DBLE(PROPS(5))*(STR_TDT(13)+STR_TDT(11)*DBLE(-1)))*DBLE(0.25)
      EEL(14)=DBLE(PROPS(4))**DBLE(-1)*DBLE(PROPS(5))**DBLE(-1)*DBLE(0.
     + 055
     + 55555555555555)*(DBLE(PROPS(4))*DBLE(-3)*(STR_TDT(10)+
     + STR_TDT(18)+STR_TDT(14)*DBLE(-2))+
     + DBLE(PROPS(5))*(STR_TDT(10)+STR_TDT(14)+
     + STR_TDT(18))*DBLE(2))
      EEL(15)=DBLE(PROPS(5))**DBLE(-1)*DBLE(PROPS(6))**DBLE(-1)*(DBLE(P
     + R
     + OPS(6))*(STR_TDT(15)+STR_TDT(17))+
     + DBLE(PROPS(5))*(STR_TDT(15)+STR_TDT(17)*DBLE(-1)))*DBLE(0.25)
      EEL(16)=DBLE(PROPS(5))**DBLE(-1)*DBLE(PROPS(6))**DBLE(-1)*(DBLE(P
     + R
     + OPS(6))*(STR_TDT(12)+STR_TDT(16))+
     + DBLE(PROPS(5))*(STR_TDT(16)+STR_TDT(12)*DBLE(-1)))*DBLE(0.25)
      EEL(17)=DBLE(PROPS(5))**DBLE(-1)*DBLE(PROPS(6))**DBLE(-1)*(DBLE(P
     + R
     + OPS(6))*(STR_TDT(15)+STR_TDT(17))+
     + DBLE(PROPS(5))*(STR_TDT(17)+STR_TDT(15)*DBLE(-1)))*DBLE(0.25)
      EEL(18)=DBLE(PROPS(4))**DBLE(-1)*DBLE(PROPS(5))**DBLE(-1)*DBLE(0.
     + 055
     + 55555555555555)*(DBLE(PROPS(4))*DBLE(-3)*(STR_TDT(10)+
     + STR_TDT(14)+STR_TDT(18)*DBLE(-2))+
     + DBLE(PROPS(5))*(STR_TDT(10)+STR_TDT(14)+
     + STR_TDT(18))*DBLE(2))
      EEL(19)=DBLE(PROPS(8))**DBLE(-1)*DBLE(PROPS(9))*STR_TDT(19)
      EEL(20)=DBLE(PROPS(8))**DBLE(-1)*DBLE(PROPS(9))*STR_TDT(20)
      EEL(21)=DBLE(PROPS(8))**DBLE(-1)*DBLE(PROPS(9))*STR_TDT(21)
      EEL(22)=DBLE(PROPS(11))**DBLE(-1)*DBLE(PROPS(12))*STR_TDT(22)
      EEL(23)=DBLE(PROPS(11))**DBLE(-1)*DBLE(PROPS(12))*STR_TDT(23)
      EEL(24)=DBLE(PROPS(11))**DBLE(-1)*DBLE(PROPS(12))*STR_TDT(24)
C     IST_SET EEL: END
      RETURN
      END
