      SUBROUTINE GETELSTRESS(STRESS,EEL,NSTR,RQ,NH,PROPS,NPROPS)
C
C      INCLUDE 'ABA_PARAM.INC'
C
      IMPLICIT NONE
C
      DOUBLE PRECISION STRESS(NSTR),EEL(NSTR),PROPS(NPROPS),RQ(NH)
      INTEGER NSTR,NH,NPROPS
      STRESS=0.D0
C     IST_SET SEL: START
      STRESS(1)=DBLE(PROPS(1))*(EEL(1)+EEL(5)+EEL(9))+
     + DBLE(PROPS(2))*DBLE(0.6666666666666666)*(EEL(5)*DBLE(-1)+
     + EEL(9)*DBLE(-1)+EEL(1)*DBLE(2))
      STRESS(2)=(DBLE(PROPS(2))+DBLE(PROPS(3)))*EEL(2)+
     + EEL(4)*(DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1))
      STRESS(3)=(DBLE(PROPS(2))+DBLE(PROPS(3)))*EEL(3)+
     + EEL(7)*(DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1))
      STRESS(4)=(DBLE(PROPS(2))+DBLE(PROPS(3)))*EEL(4)+
     + EEL(2)*(DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1))
      STRESS(5)=DBLE(PROPS(1))*(EEL(1)+EEL(5)+EEL(9))+
     + DBLE(PROPS(2))*(EEL(1)+EEL(9)+
     + EEL(5)*DBLE(-2))*DBLE(-0.6666666666666666)
      STRESS(6)=(DBLE(PROPS(2))+DBLE(PROPS(3)))*EEL(6)+
     + EEL(8)*(DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1))
      STRESS(7)=(DBLE(PROPS(2))+DBLE(PROPS(3)))*EEL(7)+
     + EEL(3)*(DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1))
      STRESS(8)=(DBLE(PROPS(2))+DBLE(PROPS(3)))*EEL(8)+
     + EEL(6)*(DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1))
      STRESS(9)=DBLE(PROPS(1))*(EEL(1)+EEL(5)+EEL(9))+
     + DBLE(PROPS(2))*(EEL(1)+EEL(5)+
     + EEL(9)*DBLE(-2))*DBLE(-0.6666666666666666)
      STRESS(10)=DBLE(PROPS(4))*(EEL(10)+EEL(14)+EEL(18))+
     + DBLE(PROPS(5))*DBLE(0.6666666666666666)*(EEL(14)*DBLE(-1)+
     + EEL(18)*DBLE(-1)+EEL(10)*DBLE(2))
      STRESS(11)=(DBLE(PROPS(5))+DBLE(PROPS(6)))*EEL(11)+
     + EEL(13)*(DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1))
      STRESS(12)=(DBLE(PROPS(5))+DBLE(PROPS(6)))*EEL(12)+
     + EEL(16)*(DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1))
      STRESS(13)=(DBLE(PROPS(5))+DBLE(PROPS(6)))*EEL(13)+
     + EEL(11)*(DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1))
      STRESS(14)=DBLE(PROPS(4))*(EEL(10)+EEL(14)+EEL(18))+
     + DBLE(PROPS(5))*(EEL(10)+EEL(18)+
     + EEL(14)*DBLE(-2))*DBLE(-0.6666666666666666)
      STRESS(15)=(DBLE(PROPS(5))+DBLE(PROPS(6)))*EEL(15)+
     + EEL(17)*(DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1))
      STRESS(16)=(DBLE(PROPS(5))+DBLE(PROPS(6)))*EEL(16)+
     + EEL(12)*(DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1))
      STRESS(17)=(DBLE(PROPS(5))+DBLE(PROPS(6)))*EEL(17)+
     + EEL(15)*(DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1))
      STRESS(18)=DBLE(PROPS(4))*(EEL(10)+EEL(14)+EEL(18))+
     + DBLE(PROPS(5))*(EEL(10)+EEL(14)+
     + EEL(18)*DBLE(-2))*DBLE(-0.6666666666666666)
      STRESS(19)=DBLE(PROPS(8))*DBLE(PROPS(9))**DBLE(-1)*EEL(19)
      STRESS(20)=DBLE(PROPS(8))*DBLE(PROPS(9))**DBLE(-1)*EEL(20)
      STRESS(21)=DBLE(PROPS(8))*DBLE(PROPS(9))**DBLE(-1)*EEL(21)
      STRESS(22)=DBLE(PROPS(11))*DBLE(PROPS(12))**DBLE(-1)*EEL(22)
      STRESS(23)=DBLE(PROPS(11))*DBLE(PROPS(12))**DBLE(-1)*EEL(23)
      STRESS(24)=DBLE(PROPS(11))*DBLE(PROPS(12))**DBLE(-1)*EEL(24)
C     IST_SET SEL: END
      RETURN
      END
      SUBROUTINE GETELMATRIX(DEL,STR_TDT,NSTR,RQ,NH,PROPS,NPROPS)
C
C      INCLUDE 'ABA_PARAM.INC'
C
      IMPLICIT NONE
C
      DOUBLE PRECISION DEL(NSTR,NSTR),STR_TDT(NSTR),PROPS(NPROPS),RQ(NH)
      INTEGER NSTR,NH,NPROPS
      DEL=0.D0
C     IST_SET DEL: START
      DEL(1,1)=DBLE(PROPS(1))+DBLE(PROPS(2))*DBLE(1.3333333333333333)
      DEL(1,5)=DBLE(PROPS(1))+DBLE(PROPS(2))*DBLE(-0.6666666666666666)
      DEL(1,9)=DBLE(PROPS(1))+DBLE(PROPS(2))*DBLE(-0.6666666666666666)
      DEL(2,2)=DBLE(PROPS(2))+DBLE(PROPS(3))
      DEL(2,4)=DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1)
      DEL(3,3)=DBLE(PROPS(2))+DBLE(PROPS(3))
      DEL(3,7)=DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1)
      DEL(4,2)=DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1)
      DEL(4,4)=DBLE(PROPS(2))+DBLE(PROPS(3))
      DEL(5,1)=DBLE(PROPS(1))+DBLE(PROPS(2))*DBLE(-0.6666666666666666)
      DEL(5,5)=DBLE(PROPS(1))+DBLE(PROPS(2))*DBLE(1.3333333333333333)
      DEL(5,9)=DBLE(PROPS(1))+DBLE(PROPS(2))*DBLE(-0.6666666666666666)
      DEL(6,6)=DBLE(PROPS(2))+DBLE(PROPS(3))
      DEL(6,8)=DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1)
      DEL(7,3)=DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1)
      DEL(7,7)=DBLE(PROPS(2))+DBLE(PROPS(3))
      DEL(8,6)=DBLE(PROPS(2))+DBLE(PROPS(3))*DBLE(-1)
      DEL(8,8)=DBLE(PROPS(2))+DBLE(PROPS(3))
      DEL(9,1)=DBLE(PROPS(1))+DBLE(PROPS(2))*DBLE(-0.6666666666666666)
      DEL(9,5)=DBLE(PROPS(1))+DBLE(PROPS(2))*DBLE(-0.6666666666666666)
      DEL(9,9)=DBLE(PROPS(1))+DBLE(PROPS(2))*DBLE(1.3333333333333333)
      DEL(10,10)=DBLE(PROPS(4))+DBLE(PROPS(5))*DBLE(1.3333333333333333)
      DEL(10,14)=DBLE(PROPS(4))+DBLE(PROPS(5))*DBLE(-0.6666666666666666
     + )
      DEL(10,18)=DBLE(PROPS(4))+DBLE(PROPS(5))*DBLE(-0.6666666666666666
     + )
      DEL(11,11)=DBLE(PROPS(5))+DBLE(PROPS(6))
      DEL(11,13)=DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1)
      DEL(12,12)=DBLE(PROPS(5))+DBLE(PROPS(6))
      DEL(12,16)=DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1)
      DEL(13,11)=DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1)
      DEL(13,13)=DBLE(PROPS(5))+DBLE(PROPS(6))
      DEL(14,10)=DBLE(PROPS(4))+DBLE(PROPS(5))*DBLE(-0.6666666666666666
     + )
      DEL(14,14)=DBLE(PROPS(4))+DBLE(PROPS(5))*DBLE(1.3333333333333333)
      DEL(14,18)=DBLE(PROPS(4))+DBLE(PROPS(5))*DBLE(-0.6666666666666666
     + )
      DEL(15,15)=DBLE(PROPS(5))+DBLE(PROPS(6))
      DEL(15,17)=DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1)
      DEL(16,12)=DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1)
      DEL(16,16)=DBLE(PROPS(5))+DBLE(PROPS(6))
      DEL(17,15)=DBLE(PROPS(5))+DBLE(PROPS(6))*DBLE(-1)
      DEL(17,17)=DBLE(PROPS(5))+DBLE(PROPS(6))
      DEL(18,10)=DBLE(PROPS(4))+DBLE(PROPS(5))*DBLE(-0.6666666666666666
     + )
      DEL(18,14)=DBLE(PROPS(4))+DBLE(PROPS(5))*DBLE(-0.6666666666666666
     + )
      DEL(18,18)=DBLE(PROPS(4))+DBLE(PROPS(5))*DBLE(1.3333333333333333)
      DEL(19,19)=DBLE(PROPS(8))*DBLE(PROPS(9))**DBLE(-1)
      DEL(20,20)=DBLE(PROPS(8))*DBLE(PROPS(9))**DBLE(-1)
      DEL(21,21)=DBLE(PROPS(8))*DBLE(PROPS(9))**DBLE(-1)
      DEL(22,22)=DBLE(PROPS(11))*DBLE(PROPS(12))**DBLE(-1)
      DEL(23,23)=DBLE(PROPS(11))*DBLE(PROPS(12))**DBLE(-1)
      DEL(24,24)=DBLE(PROPS(11))*DBLE(PROPS(12))**DBLE(-1)
C     IST_SET DEL: END
      RETURN
      END
C
      SUBROUTINE CALCHARDPARAMS(RHQ,RFQ,RHQQ,RHQS,RGQS,RQ,STR_TDT,
     1   NH,NSTR,NF,PROPS,NPROPS,NORDER)
C
C      INCLUDE 'ABA_PARAM.INC'
C
      IMPLICIT NONE
C
      DOUBLE PRECISION STR_TDT(NSTR),
     1 PROPS(NPROPS),RQ(NH),RGQS(NH,NSTR,NF),
     2 RHQ(NH,NF),RFQ(NH,NF),RHQQ(NH,NH,NF),RHQS(NH,NSTR,NF)
      INTEGER NORDER(NF)
      INTEGER NF,NPROPS,NSTR,NH
      RHQ=0.D0
      RHQQ=0.D0
      RHQS=0.D0
      RGQS=0.D0
C     IST_SET HQ: START
      RHQ(1,NORDER(1))=((DBLE(PROPS(24))*DBLE(2)*(STR_TDT(10)**DBLE(2)+
     + STR_TDT(14)**DBLE(2)+STR_TDT(18)**DBLE(2)+
     + STR_TDT(14)*STR_TDT(18)*DBLE(-1)+STR_TDT(10)*(STR_TDT(14)+
     + STR_TDT(18))*DBLE(-1)+STR_TDT(11)*STR_TDT(13)*DBLE(3)+
     + STR_TDT(12)*STR_TDT(16)*DBLE(3)+
     + STR_TDT(15)*STR_TDT(17)*DBLE(3))+
     + DBLE(PROPS(23))*(STR_TDT(14)*STR_TDT(18)*DBLE(-2)+
     + STR_TDT(10)*(STR_TDT(14)+STR_TDT(18))*DBLE(-2)+
     + STR_TDT(10)**DBLE(2)*DBLE(2)+STR_TDT(14)**DBLE(2)*DBLE(2)+
     + STR_TDT(18)**DBLE(2)*DBLE(2)+STR_TDT(11)**DBLE(2)*DBLE(3)+
     + STR_TDT(12)**DBLE(2)*DBLE(3)+STR_TDT(13)**DBLE(2)*DBLE(3)+
     + STR_TDT(15)**DBLE(2)*DBLE(3)+STR_TDT(16)**DBLE(2)*DBLE(3)+
     + STR_TDT(17)**DBLE(2)*DBLE(3))+
     + DBLE(PROPS(7))**DBLE(2)*(DBLE(PROPS(22))*DBLE(2)*(STR_TDT(1)**DBL
     + E(2)+STR_TDT(5)**DBLE(2)+STR_TDT(9)**DBLE(2)+
     + STR_TDT(5)*STR_TDT(9)*DBLE(-1)+STR_TDT(1)*(STR_TDT(5)+
     + STR_TDT(9))*DBLE(-1)+STR_TDT(2)*STR_TDT(4)*DBLE(3)+
     + STR_TDT(3)*STR_TDT(7)*DBLE(3)+
     + STR_TDT(6)*STR_TDT(8)*DBLE(3))+
     + DBLE(PROPS(21))*(STR_TDT(5)*STR_TDT(9)*DBLE(-2)+
     + STR_TDT(1)*(STR_TDT(5)+STR_TDT(9))*DBLE(-2)+
     + STR_TDT(1)**DBLE(2)*DBLE(2)+STR_TDT(5)**DBLE(2)*DBLE(2)+
     + STR_TDT(9)**DBLE(2)*DBLE(2)+STR_TDT(2)**DBLE(2)*DBLE(3)+
     + STR_TDT(3)**DBLE(2)*DBLE(3)+STR_TDT(4)**DBLE(2)*DBLE(3)+
     + STR_TDT(6)**DBLE(2)*DBLE(3)+STR_TDT(7)**DBLE(2)*DBLE(3)+
     + STR_TDT(8)**DBLE(2)*DBLE(3))))**DBLE(-1)*(DBLE(PROPS(23))**DBLE(2
     + )*(
     + DBLE(PROPS(28))*DBLE(2)*(STR_TDT(10)**DBLE(2)+
     + STR_TDT(14)**DBLE(2)+STR_TDT(18)**DBLE(2)+
     + STR_TDT(14)*STR_TDT(18)*DBLE(-1)+STR_TDT(10)*(STR_TDT(14)+
     + STR_TDT(18))*DBLE(-1)+STR_TDT(11)*STR_TDT(13)*DBLE(3)+
     + STR_TDT(12)*STR_TDT(16)*DBLE(3)+
     + STR_TDT(15)*STR_TDT(17)*DBLE(3))+
     + DBLE(PROPS(27))*(STR_TDT(14)*STR_TDT(18)*DBLE(-2)+
     + STR_TDT(10)*(STR_TDT(14)+STR_TDT(18))*DBLE(-2)+
     + STR_TDT(10)**DBLE(2)*DBLE(2)+STR_TDT(14)**DBLE(2)*DBLE(2)+
     + STR_TDT(18)**DBLE(2)*DBLE(2)+STR_TDT(11)**DBLE(2)*DBLE(3)+
     + STR_TDT(12)**DBLE(2)*DBLE(3)+STR_TDT(13)**DBLE(2)*DBLE(3)+
     + STR_TDT(15)**DBLE(2)*DBLE(3)+STR_TDT(16)**DBLE(2)*DBLE(3)+
     + STR_TDT(17)**DBLE(2)*DBLE(3)))+
     + DBLE(PROPS(24))**DBLE(2)*(DBLE(PROPS(28))*DBLE(2)*(STR_TDT(10)**D
