     + DBLE(PROPS(22))**DBLE(2)*(DBLE(PROPS(26))*DBLE(2)*(STR_TDT(1)**DB
     + LE(2)+STR_TDT(5)**DBLE(2)+STR_TDT(9)**DBLE(2)+
     + STR_TDT(5)*STR_TDT(9)*DBLE(-1)+STR_TDT(1)*(STR_TDT(5)+
     + STR_TDT(9))*DBLE(-1)+STR_TDT(2)*STR_TDT(4)*DBLE(3)+
     + STR_TDT(3)*STR_TDT(7)*DBLE(3)+
     + STR_TDT(6)*STR_TDT(8)*DBLE(3))+
     + DBLE(PROPS(25))*(STR_TDT(5)*STR_TDT(9)*DBLE(-2)+
     + STR_TDT(1)*(STR_TDT(5)+STR_TDT(9))*DBLE(-2)+
     + STR_TDT(1)**DBLE(2)*DBLE(2)+STR_TDT(5)**DBLE(2)*DBLE(2)+
     + STR_TDT(9)**DBLE(2)*DBLE(2)+STR_TDT(2)**DBLE(2)*DBLE(3)+
     + STR_TDT(3)**DBLE(2)*DBLE(3)+STR_TDT(4)**DBLE(2)*DBLE(3)+
     + STR_TDT(6)**DBLE(2)*DBLE(3)+STR_TDT(7)**DBLE(2)*DBLE(3)+
     + STR_TDT(8)**DBLE(2)*DBLE(3)))+
     + DBLE(PROPS(21))*DBLE(PROPS(22))*DBLE(2)*(DBLE(PROPS(25))*DBLE(2)*
     + (STR_TDT(1)**DBLE(2)+STR_TDT(5)**DBLE(2)+STR_TDT(9)**DBLE(2)
     + +STR_TDT(5)*STR_TDT(9)*DBLE(-1)+STR_TDT(1)*(STR_TDT(5)+
     + STR_TDT(9))*DBLE(-1)+STR_TDT(2)*STR_TDT(4)*DBLE(3)+
     + STR_TDT(3)*STR_TDT(7)*DBLE(3)+
     + STR_TDT(6)*STR_TDT(8)*DBLE(3))+
     + DBLE(PROPS(26))*(STR_TDT(5)*STR_TDT(9)*DBLE(-2)+
     + STR_TDT(1)*(STR_TDT(5)+STR_TDT(9))*DBLE(-2)+
     + STR_TDT(1)**DBLE(2)*DBLE(2)+STR_TDT(5)**DBLE(2)*DBLE(2)+
     + STR_TDT(9)**DBLE(2)*DBLE(2)+STR_TDT(2)**DBLE(2)*DBLE(3)+
     + STR_TDT(3)**DBLE(2)*DBLE(3)+STR_TDT(4)**DBLE(2)*DBLE(3)+
     + STR_TDT(6)**DBLE(2)*DBLE(3)+STR_TDT(7)**DBLE(2)*DBLE(3)+
     + STR_TDT(8)**DBLE(2)*DBLE(3)))))*(DBLE(PROPS(24))*DBLE(2)*(STR_TDT
     + (1
     + 0)*DBLE(-1)+STR_TDT(14)*DBLE(-1)+STR_TDT(18)*DBLE(2))+
     + DBLE(PROPS(23))*(STR_TDT(10)*DBLE(-2)+STR_TDT(14)*DBLE(-2)+
     + STR_TDT(18)*DBLE(4)))+
     + (DBLE(PROPS(24))*DBLE(2)*(STR_TDT(10)**DBLE(2)+
     + STR_TDT(14)**DBLE(2)+STR_TDT(18)**DBLE(2)+
     + STR_TDT(14)*STR_TDT(18)*DBLE(-1)+STR_TDT(10)*(STR_TDT(14)+
     + STR_TDT(18))*DBLE(-1)+STR_TDT(11)*STR_TDT(13)*DBLE(3)+
     + STR_TDT(12)*STR_TDT(16)*DBLE(3)+
     + STR_TDT(15)*STR_TDT(17)*DBLE(3))+
     + DBLE(PROPS(23))*(STR_TDT(14)*STR_TDT(18)*DBLE(-2)+
     + STR_TDT(10)*(STR_TDT(14)+STR_TDT(18))*DBLE(-2)+
     + STR_TDT(10)**DBLE(2)*DBLE(2)+STR_TDT(14)**DBLE(2)*DBLE(2)+
     + STR_TDT(18)**DBLE(2)*DBLE(2)+STR_TDT(11)**DBLE(2)*DBLE(3)+
     + STR_TDT(12)**DBLE(2)*DBLE(3)+STR_TDT(13)**DBLE(2)*DBLE(3)+
     + STR_TDT(15)**DBLE(2)*DBLE(3)+STR_TDT(16)**DBLE(2)*DBLE(3)+
     + STR_TDT(17)**DBLE(2)*DBLE(3))+
     + DBLE(PROPS(7))**DBLE(2)*(DBLE(PROPS(22))*DBLE(2)*(STR_TDT(1)**DBL
     + E(2)+STR_TDT(5)**DBLE(2)+STR_TDT(9)**DBLE(2)+
     + STR_TDT(5)*STR_TDT(9)*DBLE(-1)+STR_TDT(1)*(STR_TDT(5)+
     + STR_TDT(9))*DBLE(-1)+STR_TDT(2)*STR_TDT(4)*DBLE(3)+
     + STR_TDT(3)*STR_TDT(7)*DBLE(3)+
     + STR_TDT(6)*STR_TDT(8)*DBLE(3))+
     + DBLE(PROPS(21))*(STR_TDT(5)*STR_TDT(9)*DBLE(-2)+
     + STR_TDT(1)*(STR_TDT(5)+STR_TDT(9))*DBLE(-2)+
     + STR_TDT(1)**DBLE(2)*DBLE(2)+STR_TDT(5)**DBLE(2)*DBLE(2)+
     + STR_TDT(9)**DBLE(2)*DBLE(2)+STR_TDT(2)**DBLE(2)*DBLE(3)+
     + STR_TDT(3)**DBLE(2)*DBLE(3)+STR_TDT(4)**DBLE(2)*DBLE(3)+
     + STR_TDT(6)**DBLE(2)*DBLE(3)+STR_TDT(7)**DBLE(2)*DBLE(3)+
     + STR_TDT(8)**DBLE(2)*DBLE(3))))**DBLE(-1)*(DBLE(PROPS(23))**DBLE(2
     + )*(
     + DBLE(PROPS(28))*DBLE(2)*(STR_TDT(10)*DBLE(-1)+
     + STR_TDT(14)*DBLE(-1)+STR_TDT(18)*DBLE(2))+
     + DBLE(PROPS(27))*(STR_TDT(10)*DBLE(-2)+STR_TDT(14)*DBLE(-2)+
     + STR_TDT(18)*DBLE(4)))+
     + DBLE(PROPS(24))**DBLE(2)*(DBLE(PROPS(28))*DBLE(2)*(STR_TDT(10)*DB
     + LE(-1)+STR_TDT(14)*DBLE(-1)+STR_TDT(18)*DBLE(2))+
     + DBLE(PROPS(27))*(STR_TDT(10)*DBLE(-2)+STR_TDT(14)*DBLE(-2)+
     + STR_TDT(18)*DBLE(4)))+
     + DBLE(PROPS(23))*DBLE(PROPS(24))*DBLE(2)*(DBLE(PROPS(27))*DBLE(2)*
     + (STR_TDT(10)*DBLE(-1)+STR_TDT(14)*DBLE(-1)+
     + STR_TDT(18)*DBLE(2))+DBLE(PROPS(28))*(STR_TDT(10)*DBLE(-2)+
     + STR_TDT(14)*DBLE(-2)+STR_TDT(18)*DBLE(4)))))
C     IST_SET HQS: END
C     IST_SET FQ: START
      RFQ(1,NORDER(1))=DBLE(PROPS(17))*DBLE(PROPS(20))*DBLE(-1)+
     + DBLE(PROPS(16))*DBLE(PROPS(19))*(STR_TDT(1)+STR_TDT(5)+
     + STR_TDT(9))*DBLE(0.3333333333333333)
C     IST_SET FQ: END
C     IST_SET GQS: START
      RGQS(1,1,NORDER(1))=DBLE(PROPS(18))*DBLE(PROPS(19))*DBLE(0.333333
     + 333
     + 3333333)
      RGQS(1,5,NORDER(1))=DBLE(PROPS(18))*DBLE(PROPS(19))*DBLE(0.333333
     + 333
     + 3333333)
      RGQS(1,9,NORDER(1))=DBLE(PROPS(18))*DBLE(PROPS(19))*DBLE(0.333333
     + 333
     + 3333333)
C     IST_SET GQS: END
      RETURN
      END
